const $=id=>document.getElementById(id),call=(name,args)=>window.narae.call(name,args);let state,current,page=0,pageCount=0,running=false,assistant;
function modelLabel(id){return ({narae1:'나래1 · 0.6B',narae2:'나래2 · 2.4B',narae3:'나래3 · 4B'})[id]||id||'AI 연결 설정 필요';}
const status=text=>$('status').textContent=text;
function message(role,text){const intro=document.querySelector('.chat-intro');if(intro)intro.remove();const item=document.createElement('div');item.className='message '+role;item.textContent=text;$('messages').append(item);item.scrollIntoView({block:'end'});return item;}
function report(error){status(error.message||String(error));}
const action=fn=>async event=>{try{await fn(event);}catch(error){report(error);}};
function sync(value){state=value;const intro=document.querySelector('.chat-intro small');if(intro)intro.textContent=state.settings.provider==='local'?'로컬 AI는 이 컴퓨터에서 문서 내용을 처리합니다.':'AI 사용 시 선택한 문서 내용이 연결한 회사로 전송됩니다.';$('version').textContent='v'+state.version;$('activeModel').textContent=modelLabel(state.settings.model);$('agentModel').textContent=modelLabel(state.settings.model);const provider=state.settings.provider==='local'?'로컬 AI':state.settings.provider==='openai'?'ChatGPT':'Claude';$('connectionBadge').textContent=provider+' · '+(state.settings.connectionMode==='local'?'이 PC':state.settings.connectionMode==='oauth'?'OAuth':'API');$('recent').replaceChildren();for(const file of state.recent){const button=document.createElement('button');button.className='recent-item'+(current?.path===file?' active':'');button.textContent=file.split(/[\\/]/).pop();button.title=file;button.onclick=action(async()=>select(await call('openRecent',{path:file})));$('recent').append(button);}if(!state.pythonAvailable)status('설치가 필요합니다. 설치.cmd를 먼저 실행하세요.');else if(!state.hancom.hangul)status('한컴오피스 한글을 설치한 뒤 실행하세요.');}
function aiKind(config){return config.provider==='local'?(config.localSource==='external'?'external':'managed'):config.provider;}
const providerButtons=[...document.querySelectorAll('[data-ai-provider]')];let choosingAI=false,modelBusy=false;
function providerBusy(){for(const button of providerButtons)button.disabled=choosingAI||modelBusy;}
function settingsView(){const s=state.settings,kind=aiKind(s);for(const button of providerButtons)button.setAttribute('aria-pressed',String(button.dataset.aiProvider===kind));$('localAIDialog').hidden=kind!=='managed';$('cloudAIFields').hidden=!['openai','anthropic'].includes(kind);$('otherAIFields').hidden=kind!=='external';$('cloudProviderTitle').textContent=kind==='anthropic'?'Claude 연결':'GPT 연결';$('connectionMode').value=s.connectionMode==='api'?'api':'oauth';$('workspace').textContent=s.workspace;$('endpoint').value=s.endpoint;$('model').value=s.model;$('apiKey').value='';$('autoSave').checked=s.hwpAutoSave!==false;const oauth=s.connectionMode==='oauth';$('oauthFields').hidden=!oauth;$('apiFields').hidden=oauth;$('keyStatus').textContent=state.hasKey[s.provider]?'저장된 키가 있습니다. 비워 두면 유지합니다.':'아직 저장된 키가 없습니다.';$('login').textContent=s.provider==='openai'?'Continue with ChatGPT':'Claude Console 계정 연결';$('oauthExplanation').textContent=s.provider==='openai'?'ChatGPT 계정으로 연결하고 사용 권한을 승인합니다. 연결 계정의 요금제와 사용량이 적용됩니다.':'공식 Claude Console OAuth로 연결합니다. API 사용량 과금이며 Claude Pro/Max 구독과 별도입니다.';const profiles=state.auth.profiles.filter(item=>item.provider===s.provider);$('accounts').replaceChildren();for(const profile of profiles){const option=document.createElement('option');option.value=profile.id;option.textContent=profile.label+' · '+(profile.connected&&profile.sharing?'연결됨':'재연결 필요');option.selected=state.auth.selected[s.provider]===profile.id;$('accounts').append(option);}if(!profiles.length){const option=document.createElement('option');option.textContent='연결한 계정이 없습니다';option.value='';$('accounts').append(option);}$('logout').disabled=!state.auth.selected[s.provider];$('settingsStatus').textContent=state.authError||'';}
async function providerDetails(){const kind=aiKind(state.settings);if(kind==='managed')await window.naraeSettings.load('local');else if(kind==='external')await window.naraeSettings.load('external');}
async function chooseAI(kind){if(choosingAI||modelBusy)return;choosingAI=true;providerBusy();$('settingsNotice').hidden=true;try{const config=['managed','external'].includes(kind)?{provider:'local',localSource:kind}:{provider:kind};sync(await call('configure',config));settingsView();await providerDetails();}catch(error){$('settingsNotice').textContent=error.message;$('settingsNotice').hidden=false;}finally{choosingAI=false;providerBusy();}}
for(const button of providerButtons)button.onclick=()=>void chooseAI(button.dataset.aiProvider);
window.naraeAI={select:chooseAI,modelBusy:value=>{modelBusy=value;providerBusy();}};
async function saveConfig(){sync(await call('configure',{provider:state.settings.provider,connectionMode:$('connectionMode').value,endpoint:$('endpoint').value,model:$('model').value,apiKey:$('apiKey').value,hwpAutoSave:$('autoSave').checked}));settingsView();}
async function refreshModels(){const models=await call('models');$('modelOptions').replaceChildren();for(const model of models){const option=document.createElement('option');option.value=model.id;option.label=model.name;$('modelOptions').append(option);}if(!models.some(model=>model.id===$('model').value)&&models[0])$('model').value=models[0].id;$('settingsStatus').textContent=models.length+'개 모델을 불러왔습니다. 모델을 선택하고 저장하세요.';}
async function login(add){await saveConfig();$('cancelLogin').hidden=false;$('login').disabled=true;$('addAccount').disabled=true;$('settingsStatus').textContent='브라우저에서 계정 권한을 승인하세요…';try{sync(await call('login',{add}));settingsView();await refreshModels();}catch(error){$('settingsStatus').textContent=error.message;}finally{$('cancelLogin').hidden=true;$('login').disabled=false;$('addAccount').disabled=false;}}
async function select(file){if(!file)return;current=file;page=0;$('documentName').textContent=file.name;$('documentPath').textContent=file.path;for(const id of ['nativeOpen','readDocument','refreshPreview','pdfExport'])$(id).disabled=false;sync(await call('state'));status('문서를 선택했습니다. 한글에서 열거나 AI에게 작업을 요청하세요.');await preview();}
async function preview(){if(!current)return;status('한글 문서 쪽을 불러오고 있습니다…');const result=await call('preview',{path:current.path,page});pageCount=result.pages;const img=document.createElement('img');img.className='paper';img.alt=current.name+' '+(page+1)+'쪽';img.src='data:image/png;base64,'+result.image;$('documentView').replaceChildren(img);$('pageNavigation').hidden=false;$('pageNumber').textContent=(page+1)+' / '+pageCount;$('previousPage').disabled=page===0;$('nextPage').disabled=page+1>=pageCount;status('미리보기 · '+pageCount+'쪽');}
window.naraeSettings.onOpen('ai',async()=>{sync(await call('state'));settingsView();await providerDetails();});window.naraeSettings.onOpen('general',async()=>{sync(await call('state'));$('workspace').textContent=state.settings.workspace;$('autoSave').checked=state.settings.hwpAutoSave!==false;$('toolAutoAllow').checked=state.settings.toolAutoAllow===true;$('keepSchoolSession').checked=state.settings.keepSchoolSession!==false;await window.naraeDesktop.loadSettings(state);await window.naraeBrowser.loadSettings(state);$('generalSettingsStatus').textContent='';});$('settingsForm').onsubmit=action(async event=>{event.preventDefault();await saveConfig();$('settingsStatus').textContent='저장했습니다.';});
$('connectionMode').onchange=action(async()=>{sync(await call('configure',{provider:state.settings.provider,connectionMode:$('connectionMode').value}));settingsView();});
$('chooseFolder').onclick=action(async()=>{sync(await call('chooseFolder'));settingsView();});$('login').onclick=action(()=>login(false));$('addAccount').onclick=action(()=>login(true));$('cancelLogin').onclick=action(()=>call('cancelLogin'));$('accounts').onchange=action(async()=>{if($('accounts').value){sync(await call('selectAccount',{id:$('accounts').value}));settingsView();await refreshModels();}});$('logout').onclick=action(async()=>{sync(await call('logout'));settingsView();});$('usage').onclick=action(()=>call('usage'));$('loadModels').onclick=action(async()=>{await saveConfig();await refreshModels();});$('dataFolder').onclick=action(()=>call('revealData'));
$('openFile').onclick=action(async()=>select(await call('chooseFile')));$('nativeOpen').onclick=action(async()=>{await call('openNative',{path:current.path});status('기존 한글 문서 창을 열었습니다.');});$('refreshPreview').onclick=action(preview);$('previousPage').onclick=action(async()=>{if(page>0){page--;await preview();}});$('nextPage').onclick=action(async()=>{if(page+1<pageCount){page++;await preview();}});
$('readDocument').onclick=action(async()=>{const result=await call('read',{path:current.path});const text=document.createElement('pre');text.className='document-text';text.textContent=result.text;$('documentView').replaceChildren(text);$('pageNavigation').hidden=true;status('현재 열린 한글의 내용입니다.');});
$('pdfExport').onclick=action(async()=>{const result=await call('exportPDF',{path:current.path});status('PDF 저장: '+result.path);});
$('newDocument').onclick=()=>$('createDialog').showModal();$('closeCreate').onclick=()=>$('createDialog').close();$('createForm').onsubmit=action(async event=>{event.preventDefault();const result=await call('create',{path:$('newName').value,text:$('newText').value});$('createDialog').close();await select(await call('openRecent',{path:result.path}));});
$('clearHistory').onclick=action(async()=>{sync(await call('clearHistory'));$('messages').replaceChildren();});$('stopButton').onclick=action(()=>call('cancel'));
$('chatForm').onsubmit=action(async event=>{event.preventDefault();if(running)return;const prompt=$('prompt').value.trim();if(!prompt)return;running=true;message('user',prompt);assistant=message('assistant','');$('prompt').value='';$('sendButton').disabled=true;$('stopButton').hidden=false;try{await call('send',{prompt,path:current?.path});}catch(error){message('error',error.message);status(error.message);}finally{running=false;$('sendButton').disabled=false;$('stopButton').hidden=true;sync(await call('state'));}});
$('prompt').onkeydown=event=>{if(event.key==='Enter'&&(event.ctrlKey||event.metaKey)){$('chatForm').requestSubmit();event.preventDefault();}};
window.narae.onEvent(event=>{if(event.scope==='agent')return;if(event.type==='status')status(event.text);if(event.type==='text'&&assistant){assistant.textContent+=(assistant.textContent?'\n':'')+event.text;assistant.scrollIntoView({block:'end'});}if(event.type==='tool'){const item=document.createElement('div');item.className='tool-note';item.dataset.tool=event.name;item.dataset.running='true';item.textContent=event.name+' · 실행 중';$('messages').append(item);item.scrollIntoView({block:'end'});}if(event.type==='toolDone'){const item=[...document.querySelectorAll('.tool-note')].reverse().find(item=>item.dataset.tool===event.name&&item.dataset.running==='true');if(item){item.dataset.running='false';item.textContent=event.name+' · 완료';}}if(event.type==='error'){for(const item of document.querySelectorAll('.tool-note[data-running="true"]')){item.dataset.running='false';item.textContent=item.dataset.tool+' · 오류';}message('error',event.text);}if(event.type==='done')status('작업을 마쳤습니다. 미리보기 버튼으로 저장한 문서를 확인하세요.');});
for(const [source,target] of [['welcomeOpen','openFile'],['welcomeNew','newDocument']])$(source).onclick=()=>$(target).click();$('welcomeModels').onclick=()=>void window.naraeSettings.open('local');
$('settingsDataFolder').onclick=action(()=>call('revealData'));$('generalSettingsForm').onsubmit=action(async event=>{event.preventDefault();try{await window.naraeBrowser.saveEnvironment();sync(await call('configure',{browserMode:window.naraeBrowser.mode(),browserExistingOptIn:$('browserUseExisting').checked,hwpAutoSave:$('autoSave').checked,keepSchoolSession:$('keepSchoolSession').checked,closeToTray:$('closeToTray').checked,hangulShortcut:$('hangulShortcut').value,agentShortcut:$('agentShortcut').value}));$('generalSettingsStatus').textContent='저장했습니다.';$('shortcutStatus').textContent='';}catch(error){$('generalSettingsStatus').textContent=error.message;throw error;}});
call('state').then(value=>{sync(value);for(const item of value.history)message(item.role,item.content);}).catch(report);

window.naraeBrowser.onState=sync;
